    // ... (checks and effects)
274:         uint256 newStakeRSR = (FIX_ONE_256 * totalStakes + (stakeRate - 1)) / stakeRate;
275:         uint256 rsrAmount = stakeRSR - newStakeRSR;
276:         stakeRSR = newStakeRSR;

279:         (uint256 index, uint64 availableAt) = pushDraft(account, rsrAmount);
    // ...
}
```

